const MZ_ROAD_A = parse(Float64, get(ENV, "JM_MONZA_ROAD_A", "0.12"))   # road ambient fill (default 0.34)
const MZ_DARK_B = parse(Float64, get(ENV, "JM_MONZA_DARK_B", "1.05"))   # barrier brightness
