        if CTL.view != 0   # the driver figure occludes the cockpit from the in-car eye (E36 black band) → chase only
            if get(ENV,"JM_RSUSP2","0") == "1"   # E75-S8: OFF by default — raw parts are unfolded strips, see e75_exterior.md
                for it in rsusp2Items; Render.draw(prog, it, vp, bodyModel; bright=1.15, spec=RS_SPEC, ambfill=0.55); end
            end
            if RSUSP_ON    # E64 S7: high-detail rear suspension (gold nintendo shows the full articulated rear end)
                let mA = RS_BAKECLIP ? bodyModel : bodyModel*RSFIX_A,
                    mB = RS_BAKECLIP ? bodyModel : bodyModel*RSFIX_B
                    for it in rsuspItemsA; Render.draw(prog, it, vp, mA; bright=1.15, spec=RS_SPEC, ambfill=0.55); end
                    for it in rsuspItemsB; Render.draw(prog, it, vp, mB; bright=1.15, spec=RS_SPEC, ambfill=0.55); end
                end
            end
            for it in driverItems; Render.draw(prog, it, vp, bodyModel; bright=1.2, spec=0.10, ambfill=0.55); end
            helmModel = bodyModel * Render.translate(HELM_OFF[1],HELM_OFF[2],HELM_OFF[3])
            for it in helmItems; Render.draw(prog, it, vp, helmModel; bright=1.2, spec=0.12, ambfill=0.60); end
        end
        # gauge cluster (real GPL dash7A dial faces): the dash sits BELOW the scuttle/black panels in the
        # mesh, so it's occluded from the driver's eye → draw it depth-test-OFF so the dials read on the
        # dash, near-unlit (bright + ambfill) so the faces are legible.  Only matters in the cockpit view.
        # E59 parity: bright 1.6/ambfill 0.95 over-exposed the dash — the GPL gold cockpit has a MATTE
        # BLACK dash with crisp white-on-black dials; ours read as a washed-out silver plank.  Near-unlit
        # but at unity brightness keeps the dials legible AND the panel black.  JM_DASH_B/JM_DASH_A tune.
        dash_b = parse(Float64, get(ENV,"JM_DASH_B","1.2")); dash_a = parse(Float64, get(ENV,"JM_DASH_A","0.9"))   # E62: gold cockpit dials read crisp white-on-black; 1.0/0.60 left ours dim — lift fill so the dial faces/markings are legible
        if CTL.view == 0
            glDisable(GL_DEPTH_TEST)
            for it in gaugeItems; Render.draw(prog, it, vp, bodyModel*GAUGEFLIP; bright=dash_b, spec=0.0, ambfill=dash_a); end
            glEnable(GL_DEPTH_TEST)
        else
            for it in gaugeItems; Render.draw(prog, it, vp, bodyModel*GAUGEFLIP; bright=dash_b, spec=0.0, ambfill=dash_a); end
        end
        # (AI grid drawn in drawworld — shared with the E64 mirror pass)
        # E59 parity: default lighting rendered the tyres as solid BLACK silhouettes from the cockpit —
        # the GPL gold cockpit shows readable dark-grey tread + sidewall.  Lift the fill (not the sun).
        # AXLE-1 S2 (2026-09-14): JM_NO_WHEELS=1 is a DIAGNOSTIC -- it drops the road wheels from
        # this pass so the driveshafts behind them can be photographed. S1 fixed the axles'
        # placement arithmetically and said plainly that the on-screen change was modest because
        # the wheel and gearbox occlude the shaft; a matched-viewpoint capture confirmed that the
        # gap is not visible from the rear-corner camera either. Never ship this on.
        for (wx,wz,steer,r,nm) in WHEELS, it in WHEELITEMS[nm]
            is_loose(nm) && continue
            get(ENV,"JM_NO_WHEELS","0") != "0" && continue
            Render.draw(prog, it, vp, wheelmat(wx,wz,steer,r); bright=1.0, ambfill=0.75)
        end
        for (lx,ly,lz,_,_,_,sp,_,nm) in LOOSE_WHEELS, it in WHEELITEMS[nm]
            Render.draw(prog, it, vp, loosemat(lx,ly,lz,sp); bright=1.0, ambfill=0.75)
        end
        # front suspension wishbones — ahead of the cockpit, visible through the plexiglass (PO gold standard)
        for it in fsuspItems; Render.draw(prog, it, vp, bodyModel; bright=1.1, spec=0.15, ambfill=0.5); end
        # rear-view mirrors — re-placed onto the cowl/plexiglass, faces tilted toward the eye (GPL look).
        # E64: with the RTT live, the silver disc is just the RIM/backing — the glass quad on top
        # carries the actual rear view (round-masked sample of the mirror FBO, uMirrorGlass).
        for it in mirrorItems; Render.draw(prog, it, vp, bodyModel*MIRRORMAT; bright=1.25, spec=0.30, ambfill=0.75, depthbias=true); end   # disc/rim (E106-S8: biased over the lotd pod faces)
        if mirror_live
            for it in mirGlassItems; Render.draw(prog, it, vp, bodyModel*MIRRORMAT; mirrorglass=true, depthbias=true); end   # live glass (E106-S8: biased)
        end
        # steering wheel — spin about its column axis with steering input
        # CARGOLD-1 S9 (PO 2026-09-07: "Steering wheel is also installed upside down"): the gold's three spokes
        # are a Y (two up, one down to the hub); ours had the single spoke UP. A half turn about the column
        # (JM_SW_ROT, degrees, default 180) puts the wheel as the gold has it; the steering input adds to it.
        swModel = bodyModel * Render.translate(SWCENTER) * Render.rotaxis(SWAXIS, Float32(HSIGN*inp.steer*2.5 + SW_ROT)) * Render.translate(-SWCENTER[1], -SWCENTER[2], -SWCENTER[3])
        for it in swItems; Render.draw(prog, it, vp, swModel; bright=1.2, ambfill=0.34); end
        if CTL.view == 0 && !isempty(shiftItems) && SHIFT_PIVOT !== nothing     # COCKPIT-2 S3: the lever follows the gear
            _tn = time(); _dt = SHIFT_TW[] == 0.0 ? 1f0 : Float32(clamp(_tn - SHIFT_TW[], 0.0, 0.1)); SHIFT_TW[] = _tn
            shm = bodyModel * shift_model(cs.gear, _dt)
            for it in shiftItems; Render.draw(prog, it, vp, shm; bright=0.95, ambfill=0.45); end   # gold: dark wood, not lit orange
        end
        # E64 S2 (Z-CK4): gloved hands + forearms, cockpit view only (the chase driver figure has its
        # own DRIVER_TEX arms).  Hands turn with the wheel, forearms stay put — GPL-era articulation.
        # The lotarms mesh is authored in a positioner-local frame (D12 posmat-clamp family): raw it
        # sits FORWARD of the wheel (x 0.68…1.01) and too high (y→0.52) → the old "giant silver arms".
        # ARMFIX mirrors it back through the wheel plane toward the driver + squashes it under the eye.
        if HANDS && CTL.view == 0
            _hcull = glIsEnabled(GL_CULL_FACE) == GL_TRUE
            HAND_CULL || glDisable(GL_CULL_FACE)          # HANDS-1 S2: A/B the gloves two-sided (inside-out fists?)
            if ARMS
                # HANDS-1 S4: in lotus.3do the arms and gloves share the steering-wheel assembly's positioner (node 15060), so
                # GPL turns the arms with the wheel; JM_ARMS_ON_WHEEL=1 draws them with the gloves' transform, no ARMFIX (A/B).
                if ARMS2 && length(armLR) == 2 && SLEEVE_ENDS[1] !== nothing && SLEEVE_ENDS[2] !== nothing
                    swRel = Render.translate(SWCENTER) * Render.rotaxis(SWAXIS, Float32(HSIGN*inp.steer*2.5 + SW_ROT)) * Render.translate(-SWCENTER[1], -SWCENTER[2], -SWCENTER[3])
                    for (k, sgn) in ((1, 1), (2, -1))          # armLR[1] = z > 0 with gripmat(+1), as handLR
                        W, E, nf = SLEEVE_ENDS[k]
                        h = swRel * gripmat(sgn) * Float32[W[1], W[2], W[3], 1f0]
                        S = (SHOULDER[1], SHOULDER[2], sgn*SHOULDER[3])
                        if SLEEVE_HOLD && SLEEVE_NREF[k] === nothing    # the straight-wheel face normal, once
                            sw0 = Render.translate(SWCENTER) * Render.rotaxis(SWAXIS, Float32(SW_ROT)) * Render.translate(-SWCENTER[1], -SWCENTER[2], -SWCENTER[3])
                            h0 = sw0 * gripmat(sgn) * Float32[W[1], W[2], W[3], 1f0]
                            sleeve_mat(W, E, (h0[1], h0[2], h0[3]), S, nf); SLEEVE_NREF[k] = SLEEVE_LASTR[] * collect(nf)
                        end
                        # HANDS-2 S3: lit toward the gold's white sleeve (it read grey at 1.15 / 0.60)
                        # COCKPIT-2 S4 (PO 2026-10-07: "the wrists are see-through"): the sleeve's end stopped AT the glove's
                        # cuff point, and the glove is an open band round the rim -- between them the dash showed through.
                        # Run the sleeve on along its own line ARM_INTO metres into the glove so the two overlap.
                        _into = haskey(ENV, "JM_ARM_INTO") ? parse(Float64, ENV["JM_ARM_INTO"]) : ARM_INTO
                        _d = (h[1] - S[1], h[2] - S[2], h[3] - S[3]); _l = sqrt(_d[1]^2 + _d[2]^2 + _d[3]^2)
                        h = _l > 1e-6 ? (h[1] + _into*_d[1]/_l, h[2] + _into*_d[2]/_l, h[3] + _into*_d[3]/_l) : h
                        Render.draw(prog, armLR[k], vp, bodyModel * sleeve_mat(W, E, (h[1], h[2], h[3]), S, nf; target = SLEEVE_HOLD ? SLEEVE_NREF[k] : nothing);
                                    bright=1.35, spec=0.05, ambfill=0.85)
                    end
                else
                    _amod = ARMS_ON_WHEEL ? swModel : bodyModel*ARMFIX
                    for it in armItems;  Render.draw(prog, it, vp, _amod; bright=1.15, spec=0.05, ambfill=0.60); end
                end
            end
            if length(handLR) == 2                      # left fist +grip, right fist −grip → gold's 10-and-2
                Render.draw(prog, handLR[1], vp, swModel*gripmat(+1); bright=1.15, spec=0.05, ambfill=0.60)
                Render.draw(prog, handLR[2], vp, swModel*gripmat(-1); bright=1.15, spec=0.05, ambfill=0.60)
            else
                for it in handItems; Render.draw(prog, it, vp, swModel; bright=1.15, spec=0.05, ambfill=0.60); end
            end
            (!HAND_CULL && _hcull) && glEnable(GL_CULL_FACE)
        end
        # plexiglass WINDSCREEN — drawn LAST, FAINTLY VISIBLE glass (PO: it had vanished at 0.16), depth-write
        # OFF so the front suspension + track read through it (GPL gold standard) but the screen still reads as
        # a tinted curved plexiglass, not a bright opaque gold rim.  JM_WIND_ALPHA tunes it.
        if !isempty(visorItems) && VISOR_ALPHA > 0      # COCKPIT-GOLD-1: the perspex windscreen, every view
            glDepthMask(GL_FALSE)
            for it in visorItems; Render.draw(prog, it, vp, bodyModel; bright=1.0, spec=0.35, ambfill=0.7, alpha=VISOR_ALPHA, depthbias=true); end
            glDepthMask(GL_TRUE)
        end
        if WIND_ALPHA > 0
            glDepthMask(GL_FALSE)
            # PO: flatter, dimmer lighting so the leather scuttle reads as smooth matte tan — not stark
            # cream "plywood" wedges clashing with the dark footwell notch the (omitted) driver would fill.
            for it in windItems; Render.draw(prog, it, vp, bodyModel; bright=WIND_B, spec=0.02, ambfill=WIND_A, alpha=WIND_ALPHA, depthbias=true); end   # E106-S8: biased over the lotd frame faces
            glDepthMask(GL_TRUE)
        end
        α_tc = clamp(dt/0.10, 0.0, 1.0)              # smooth the traction-circle display (coarse-mesh Fz spikes → no flicker)
        tc_hud = ntuple(i -> ntuple(j -> tc_hud[i][j] + (cs.tc[i][j]-tc_hud[i][j])*α_tc, 3), 4)
        ALLOCPROF > 0 && (ALLOC_MARK[4] = Base.gc_bytes())   # main world pass
        DSTAT && (GPUSYNC && glFinish(); DS_T[4] = time(); DS_N[3] = Render.NDRAW[]; DS_N[6] = Render.NTRI[])
        _t_hud = time()
        Render.hud_draw(hudprog, hudvao, hudvbo,
            Render.compose_hud(W, H, cs.v*3.6, cs.gear, cs.rpm, 9500.0, inp.throttle, inp.brake, inp.clutch, tc_hud;
                               lastlap=(FONT === nothing ? (SMOKE ? 94.3 : last_lap) : 0.0),   # TEXTHUD-1: the text rows carry these; no double readout
                               bestlap=(FONT === nothing ? (SMOKE ? 92.1 : best_lap) : 0.0), manual=!CTL.auto,
                               countdown=cd_left[],
                               # STARTSEQ-1: the spacebar keycap, pulsing at 1 Hz, while unarmed.
                               startprompt=(START_ARM && !cd_armed[] && HOLD_START && !race_go[] &&
                                            phase[] == :race && COUNTDOWN > 0) ? mod(cs.t, 1.0) : -1.0,
                               clutchgate=(CLUTCH_GATE[] > 0 ? inp.clutch : -1.0),
                               # PO 2026-09-04: "no indication that race is over". The finish was
                               # announced only in the window title and on stdout; show it in the
                               # game. player_finpos is set when race_done latches.
                               finished=(race_done ? player_finpos[] : 0)), W, H)
        # TEXTHUD-1 (GOLDMATCH-JR-1 S1, 2026-09-17): the gold's timing overlay, in its layout -- lap
        # rows top-left (I = this lap, B = best, L = last), Track Position top-right with names and
        # metres to each car, the player's row amber. Only what the sim can honestly report is
        # shown: no sectors, no Relative tables yet (those need per-car lap clocks -- S2).
        if FONT !== nothing
            # The gold's rows sit on an opaque black band across the top of the frame (its overlay is
            # not blended over the scene). Same here: one flat quad through the HUD program, then text.
            # S2: the band must also cover the Track Position table (three lap rows alone left the
            # table's lower rows blended over the grandstand).
            nrows = (IS_RACE && !isempty(AICARS)) ? max(3, min(7, 1 + length(AICARS)) + 1) : 3
            bv = empty!(HUD_BV); Render.hquad!(bv, 0.0, 0.0, Float64(W), nrows*FONT.lineh + 12.0, (0.0, 0.0, 0.0))
            Render.hud_draw(hudprog, hudvao, hudvbo, bv, W, H)
            tv = empty!(HUD_TV); fy = 6.0; fx = 8.0
            cur = (race_go[] && !race_done) ? cs.t - lap_t0 : (SMOKE ? 23.27 : 0.0)
            Render.text!(tv, FONT, fx, fy,            "I  " * lapfmt(cur),                              (1.0, 0.45, 1.0))
            Render.text!(tv, FONT, fx, fy + FONT.lineh, "B  " * lapfmt(SMOKE ? 92.1 : best_lap),           (0.75, 0.75, 0.75))
            Render.text!(tv, FONT, fx, fy + 2FONT.lineh, "L  " * lapfmt(SMOKE ? 94.3 : last_lap),          (0.45, 0.95, 0.45))
            if IS_RACE && !isempty(AICARS)
                st = standings(); ppy = 0.0
                for e in st; e[1] == 0 && (ppy = e[2]); end
                lapsN = length(st) > 0 ? cs.laps + 1 : 1
                tx = W - 8.0 - 300.0
                Render.text!(tv, FONT, tx, fy, "Track Position ($(lapsN)L)", (0.95, 0.95, 0.95))
                for (i, e) in enumerate(st)
                    i > 7 && break
                    gapm = round(Int, (e[2] - ppy) * LAPLEN)
                    col = e[1] == 0 ? (1.0, 0.82, 0.35) : (0.95, 0.95, 0.95)
                    Render.text!(tv, FONT, tx, fy + i*FONT.lineh, string(i, " ", texthud_name(e[1])), col)
                    Render.text!(tv, FONT, tx + 190.0, fy + i*FONT.lineh, (gapm >= 0 ? "+" : "") * string(gapm) * "m", col)
                end
            end
            Render.text_draw(textprog, textvao, textvbo, FONT, tv, W, H)
            # TRACKSEG-1: the section name, centred in the black timing band above the 3-D view. PO 2026-10-04 (2):
            # "less obtrusive ... higher vertically ... no colored text window behind the words, about the same contrast
            # (but larger font) as the other text above the 3D window" -- the band's own light grey, a larger regular face.
            if !isempty(SECTIONS) && SEGNAME_SECS > 0
                SEG[] = section_update(SECTIONS, cs.lapdist, LAPLEN, cs.t, SEG[]...)
                if cs.t - SEG[][3] < SEGNAME_SECS || !isempty(SEGNAME_FORCE)
                    msg = isempty(SEGNAME_FORCE) ? SEG[][2] : SEGNAME_FORCE; tw = Render.text_width(SEGFONT, msg)
                    bandh = nrows*FONT.lineh + 12.0
                    st = empty!(HUD_ST); Render.text!(st, SEGFONT, (W - tw)/2, max(2.0, (bandh - SEGFONT.lineh)/2), msg, (0.95, 0.95, 0.95))
                    Render.text_draw(textprog, textvao, textvbo, SEGFONT, st, W, H)
                end
            end
            # RACEEND-1 (PO 2026-09-19, WG race: "there should be a graphical signal when the race is
            # over"). Until now the finish was a small line in the standings box and the window title.
            # Now: a chequered strip across the frame under the HUD band and a large centred banner,
            # for RACEEND_SECS seconds after the flag (then just the strip stays, so a late look still
            # says the race is over). JM_RACEEND_SECS overrides; 0 disables the banner.
            if IS_RACE && race_done && RACEEND_SECS > 0
                RACEEND_T0[] < 0 && (RACEEND_T0[] = cs.t)
                sq = 28.0; y0 = nrows*FONT.lineh + 12.0
                cv = Float32[]
                for (r, yy) in enumerate((y0, y0 + sq))
                    for (c, xx) in enumerate(0.0:sq:Float64(W))
                        Render.hquad!(cv, xx, yy, sq, sq, iseven(r + c) ? (0.05, 0.05, 0.05) : (0.97, 0.97, 0.97))
                    end
                end
                Render.hud_draw(hudprog, hudvao, hudvbo, cv, W, H)
                if cs.t - RACEEND_T0[] < RACEEND_SECS
                    msg = "RACE FINISHED" * (isempty(AICARS) ? "" : " - P$(player_finpos[]) of $(length(AICARS)+1)")
                    sub = "best lap $(fmt_lap(best_lap))   -   Esc to leave"
                    sc = 3.0; tw = Render.text_width(FONT, msg; scale=sc); sw = Render.text_width(FONT, sub; scale=1.4)
                    bx = (W - tw)/2 - 24; by = H*0.30
                    bg = Float32[]; Render.hquad!(bg, bx, by - 10, tw + 48, sc*FONT.lineh + 1.4*FONT.lineh + 28, (0.0, 0.0, 0.0))
                    Render.hud_draw(hudprog, hudvao, hudvbo, bg, W, H)
                    fv = Float32[]
                    Render.text!(fv, FONT, (W - tw)/2, by, msg, (1.0, 0.85, 0.2); scale=sc)
                    Render.text!(fv, FONT, (W - sw)/2, by + sc*FONT.lineh + 8, sub, (0.95, 0.95, 0.95); scale=1.4)
                    Render.text_draw(textprog, textvao, textvbo, FONT, fv, W, H)
                end
            end
        end
        CLUTCH_GATE[] > 0 && (CLUTCH_GATE[] -= dt)
        # E80 (PO 2026-08-27): "frame rate was low (10 frames/sec or so) in cockpit view, better in
        # nintendo view ... no excuse for 10 frames/sec on a PC with a 6 GB nvidia graphics card".
        # Report the frame time per VIEW, because the cockpit/chase asymmetry is the whole clue:
        # the same scene from two cameras, so anything that costs the same in both is not the cause.
        # JM_FPSDIAG=<n> prints every n frames (default 120).
        FRAMEPROF > 0 && (PROF_HUD[] += time() - _t_hud)
        if FRAMEPROF > 0
            PROF_N[] += 1
            if PROF_N[] >= FRAMEPROF
                nn = PROF_N[]
                # PROF_TOT is filled by the FPSDIAG accumulator below when it is also on; when it is
                # not, report the phases alone rather than a percentage of an unknown whole. A split
                # that silently divides by a total nobody measured is the kind of confident-wrong
                # number this project keeps booking.
                tot = PROF_TOT[] > 0 ? PROF_TOT[]/nn*1000 : NaN
                println("  [frameprof] ", nn, " frames:  world ", round(1000*PROF_WORLD[]/nn, digits=2),
                        " ms   hud ", round(1000*PROF_HUD[]/nn, digits=2), " ms",
                        "   [depth ", round(1000*PROF_DEPTH[]/nn, digits=2), " track ", round(1000*PROF_TRACK[]/nn, digits=2),
                        " objects ", round(1000*PROF_OBJ[]/nn, digits=2), " billboards ", round(1000*PROF_BB[]/nn, digits=2),
                        " cars ", round(1000*PROF_CARS[]/nn, digits=2), "]",
                        isnan(tot) ? "   (total not measured -- set JM_FPSDIAG too)" :
                                     "   of " * string(round(tot, digits=2)) * " ms total")
                flush(stdout)
                PROF_WORLD[] = 0.0; PROF_HUD[] = 0.0; PROF_N[] = 0; PROF_TOT[] = 0.0
                PROF_DEPTH[] = 0.0; PROF_TRACK[] = 0.0; PROF_OBJ[] = 0.0; PROF_BB[] = 0.0; PROF_CARS[] = 0.0
            end
        end
        if FPSDIAG > 0
            _now = time()
            if FPS_T0[] > 0
                FPS_ACC[] += _now - FPS_T0[]; FPS_N[] += 1; FRAMEPROF > 0 && (PROF_TOT[] += _now - FPS_T0[])
                push!(FPS_DTS, _now - FPS_T0[])   # PACE-1: frame-interval spread, not just the mean
                if FPS_N[] >= FPSDIAG
                    _ms = 1000*FPS_ACC[]/FPS_N[]
                    # SPA-FPS-1 (PO 2026-09-06: "spa has low frame rate at places, but the ring does not"): each
                    # report carries WHERE (lapdist) and HOW MUCH is in draw range (objects within OBJ_CULL2,
                    # billboards within BB range) -- the frame time's suspects, not just its value.
                    _hr = JuliaMotor.hat(TRKSURF, cs.x, cs.z)
                    _nobj = count(o -> (o[4][1] - cs.x)^2 + (-o[4][3] - cs.z)^2 < OBJ_CULL2, OBJECTS)
                    println("  [fps] view=", CTL.view == 0 ? "cockpit" : "chase  ",
                            "  ", round(1000/_ms, digits=1), " fps  (", round(_ms, digits=1), " ms/frame)",
                            "  s=", _hr.found ? round(Int, _hr.lapdist) : -1, "  objs_in_range=", _nobj, "/", length(OBJECTS),
                            "  billboards=", length(BILLBOARDS), "  trees=", length(STATICTREES))
                    if !isempty(FPS_DTS)
                        _d = sort(FPS_DTS) .* 1000
                        println("  [pace] frame interval ms: p10 ", round(_d[max(1, length(_d)÷10)], digits=1), "  p50 ", round(_d[max(1, length(_d)÷2)], digits=1),
                                "  p90 ", round(_d[max(1, 9*length(_d)÷10)], digits=1), "  max ", round(_d[end], digits=1), "  >25ms ", count(>(25.0), _d), "/", length(_d), "  (interval ", PACE_INT[], ")")
                        empty!(FPS_DTS)
                    end
                    flush(stdout); FPS_ACC[] = 0.0; FPS_N[] = 0
                end
            end
            FPS_T0[] = _now
        end
        # PACE-1: a frame that cannot make 60 Hz under vsync is shown for an uneven 1-2-3 refreshes (the PO's
        # "jerky, especially at Spa": Spa 28-31 fps, Ring 37-41 fps measured). When the WORK time (frame start
        # to here, excluding the vsync wait) stays over JM_PACE_HI ms (19.0), present every 2nd refresh -- a
        # steady 30 Hz, every frame held exactly two refreshes -- and return to 60 Hz below JM_PACE_LO (15.0).
        # The physics dt is the real frame time, so motion stays true either way. JM_PACE=0 disables.
        if ALLOCPROF > 0
            ALLOC_MARK[5] = Base.gc_bytes()                     # HUD etc.
            for k in 1:4; ALLOC_ACC[k] += ALLOC_MARK[k+1] - ALLOC_MARK[k]; end
            ALLOC_N[] += 1
            if ALLOC_N[] >= ALLOCPROF
                println("  [alloc] KB/frame: sim ", round(Int, ALLOC_ACC[1]/ALLOC_N[]/1024), "  shadow+mirror ", round(Int, ALLOC_ACC[2]/ALLOC_N[]/1024),
                        "  world ", round(Int, ALLOC_ACC[3]/ALLOC_N[]/1024), "  hud ", round(Int, ALLOC_ACC[4]/ALLOC_N[]/1024)); flush(stdout)
                fill!(ALLOC_ACC, 0); ALLOC_N[] = 0
            end
        end
        if PACE_ON && (!SMOKE || haskey(ENV, "JM_PACE_TEST"))
            # PERF-3: the first frame (4.9 s of JIT) seeded the EMA and every session opened at 30 Hz; a single
            # crash/GC hitch (288 ms) flipped it again. Skip the warm-up and clamp each sample, so only a
            # SUSTAINED over-budget load (~30+ frames) drops the rate.
            _wk = min(time() - now, 1.5 * PACE_HI)
            if frames > PACE_WARM
                PACE_EMA[] = PACE_EMA[] == 0.0 ? _wk : 0.95*PACE_EMA[] + 0.05*_wk
            end
            if PACE_INT[] == 1 && PACE_EMA[] > PACE_HI
                PACE_INT[] = 2; GLFW.SwapInterval(2); println("  [pace] work ", round(1000*PACE_EMA[], digits=1), " ms -> steady 30 Hz"); flush(stdout)
            elseif PACE_INT[] == 2 && PACE_EMA[] < PACE_LO
                PACE_INT[] = 1; GLFW.SwapInterval(1); println("  [pace] work ", round(1000*PACE_EMA[], digits=1), " ms -> 60 Hz"); flush(stdout)
            end
        end
        # PERF-3: the automatic collector let ~190 MB pile up and then paused 30-60 ms (2-4 dropped frames every
        # ~4 s at the Ring: the PO's "jerky"). A young-generation collection every GC_EVERY frames, issued here
        # while the GPU is still finishing the frame (the CPU would otherwise just wait in SwapBuffers), keeps each
        # pause small enough to fit the slack. JM_GC_EVERY=0 leaves it to the automatic collector.
        if GC_EVERY > 0 && frames % GC_EVERY == 0 && frames > 0
            _tg = time(); GC.gc(false); _tg = time() - _tg
            GC_MS[1] += _tg; GC_MS[2] = max(GC_MS[2], _tg); GC_MS[3] += 1
            if FPSDIAG > 0 && GC_MS[3] >= 20
                println("  [gc] young collections: mean ", round(1000GC_MS[1]/GC_MS[3], digits=2), " ms  max ", round(1000GC_MS[2], digits=2), " ms  (every ", GC_EVERY, " frames)"); flush(stdout)
                fill!(GC_MS, 0.0)
            end
        end
        DSTAT && (GPUSYNC && glFinish(); DS_T[5] = time())
        GLFW.SwapBuffers(win)
        if GPUQ > 0                                   # PERF-4 S3: at most one frame queued in the driver
            _tq = time()
            if GPUQ_FENCE[] != C_NULL
                glClientWaitSync(GPUQ_FENCE[], GL_SYNC_FLUSH_COMMANDS_BIT, UInt64(100_000_000)); glDeleteSync(GPUQ_FENCE[])
            end
            GPUQ_FENCE[] = glFenceSync(GL_SYNC_GPU_COMMANDS_COMPLETE, 0)
            _w = time() - _tq; GPUQ_WAIT[1] += _w; GPUQ_WAIT[2] += 1; GPUQ_WAIT[3] = max(GPUQ_WAIT[3], _w)
            if GPUQ_DIAG > 0 && GPUQ_WAIT[2] >= GPUQ_DIAG
                println("  [gpuq] fence wait mean ", round(1000GPUQ_WAIT[1]/GPUQ_WAIT[2], digits = 2), " ms  max ",
                        round(1000GPUQ_WAIT[3], digits = 1), " ms  fps ", round(FRAME_FPS[], digits = 1)); flush(stdout)
                fill!(GPUQ_WAIT, 0.0)
            end
        end
        if DSTAT
            DS_T[6] = time()
            for k in 1:5; DS_ACC[k] += DS_T[k+1] - DS_T[k]; end
            for k in 1:6; DS_NA[k] += DS_N[k]; end
            DS_CNT[] += 1
            if DS_CNT[] >= 240
                c = DS_CNT[]; f(x) = round(1000x/c, digits=2)
                println("  [drawstats] FRAME ", f(DS_LOOP[]), " ms  = SIM ", f(DS_SIMACC[1]), " (player phys ", f(DS_SIMACC[2]), ", AI phys ", f(DS_SIMACC[3]), ")  shadow ", f(DS_ACC[1]), "  mirror ", f(DS_ACC[2]), "  main ", f(DS_ACC[3]), "  hud ", f(DS_ACC[4]), "  swap ", f(DS_ACC[5]),
                        "   draws: shadow ", DS_NA[1]÷c, " mirror ", (DS_NA[2]-DS_NA[1])÷c, " main ", (DS_NA[3]-DS_NA[2])÷c,
                        "   ktris: shadow ", DS_NA[4]÷c÷1000, " mirror ", (DS_NA[5]-DS_NA[4])÷c÷1000, " main ", (DS_NA[6]-DS_NA[5])÷c÷1000, GPUSYNC ? "  (GPU-synced)" : "")
                flush(stdout); fill!(DS_ACC, 0.0); fill!(DS_NA, 0); fill!(DS_SIMACC, 0.0); DS_LOOP[] = 0.0; DS_CNT[] = 0
            end
        end
        # JM_FRAMEDUMP="<start>:<count>" dumps CONSECUTIVE frames, which the existing JM_SHOTS
        # cannot: it settles and dumps one frame per teleport, so it can photograph a scene but
        # never a TEMPORAL artefact. The PO's strobing mirrors are exactly that -- a single frame
        # cannot show them. Frames go to JM_FRAMEDUMP_DIR (default alongside the build tree, NOT
        # /tmp: 1920x1080 PPMs are ~6 MB each and /tmp here is a quota'd tmpfs that has already
        # broken a session).
        if !isempty(FRAMEDUMP) && FRAMEDUMP[1] <= frames < FRAMEDUMP[1] + FRAMEDUMP[2]
            buf=Vector{UInt8}(undef,W*H*3); glReadPixels(0,0,W,H,GL_RGB,GL_UNSIGNED_BYTE,buf)
            fn = joinpath(FRAMEDUMP_DIR, "jmfd_" * lpad(frames, 5, '0') * ".ppm")
            open(fn,"w") do io; write(io,"P6\n$W $H\n255\n")
                for y in H:-1:1, x in 1:W; o=((y-1)*W+(x-1))*3; write(io,buf[o+1],buf[o+2],buf[o+3]); end; end
            frames == FRAMEDUMP[1] + FRAMEDUMP[2] - 1 && (println("  JM_FRAMEDUMP: ", FRAMEDUMP[2],
                " consecutive frames -> ", FRAMEDUMP_DIR); flush(stdout))
        end
        if SMOKE && frames == 38 && isempty(SHOTS)  # headless self-test: dump one frame
            buf=Vector{UInt8}(undef,W*H*3); glReadPixels(0,0,W,H,GL_RGB,GL_UNSIGNED_BYTE,buf)
            open(get(ENV,"JM_DUMP","/tmp/zand_hud.ppm"),"w") do io; write(io,"P6\n$W $H\n255\n")
                for y in H:-1:1, x in 1:W; o=((y-1)*W+(x-1))*3; write(io,buf[o+1],buf[o+2],buf[o+3]); end; end
        end
        # JM_SHOT_AT: time-triggered captures (see SHOTS_AT). Arm on the trigger, dump SHOT_SETTLE
        # frames later so a view switch has settled; in a replay the clock is the replay clock.
        if !isempty(SHOTS_AT)
            _tnow = REPLAY ? rep_rt[] : cs.t
            for (k, ts) in enumerate(SHOTS_AT)
                SHOTS_AT_ARMED[k] == -2 && continue
                if SHOTS_AT_ARMED[k] < 0
                    fire = startswith(ts.when, "finish+") ? (race_done && RACEEND_T0[] >= 0 && cs.t - RACEEND_T0[] >= parse(Float64, ts.when[8:end])) :
                                                          (_tnow >= parse(Float64, ts.when))
                    if fire
                        SHOTS_AT_ARMED[k] = frames; ts.view >= 0 && (CTL.view = ts.view)
                        println("  JM_SHOT_AT: armed ", ts.name, " at t=", round(_tnow, digits=2)); flush(stdout)
                    end
                elseif frames - SHOTS_AT_ARMED[k] >= SHOT_SETTLE
                    buf=Vector{UInt8}(undef,W*H*3); glReadPixels(0,0,W,H,GL_RGB,GL_UNSIGNED_BYTE,buf)
                    open(joinpath(SHOTS_DIR, ts.name * ".ppm"),"w") do io; write(io,"P6\n$W $H\n255\n")
                        for y in H:-1:1, x in 1:W; o=((y-1)*W+(x-1))*3; write(io,buf[o+1],buf[o+2],buf[o+3]); end; end
                    println("  JM_SHOT_AT: dumped ", ts.name); flush(stdout)
                    SHOTS_AT_ARMED[k] = -2
                    all(==(-2), SHOTS_AT_ARMED) && haskey(ENV, "JM_SHOT_AT_EXIT") && break
                end
            end
        end
        if SMOKE && !isempty(AICAM_SEQ) && frames >= 40
            seg = (frames - 40) ÷ AICAM_SEG + 1
            if seg <= length(AICAM_SEQ)
                (AICAM_R[], AIVIEW_R[]) = AICAM_SEQ[seg]
                if (frames - 40) % AICAM_SEG == AICAM_SEG - 1
                    buf=Vector{UInt8}(undef,W*H*3); glReadPixels(0,0,W,H,GL_RGB,GL_UNSIGNED_BYTE,buf)
                    open(joinpath(SHOTS_DIR, "aiseq_$(seg)_$(AICAM_R[])_$(AIVIEW_R[]).ppm"),"w") do io; write(io,"P6\n$W $H\n255\n")
                        for y in H:-1:1, x in 1:W; o=((y-1)*W+(x-1))*3; write(io,buf[o+1],buf[o+2],buf[o+3]); end; end
                end
            end
        end
        # E59 multi-shot: dump the settled frame for the current shot, then teleport to the next.
        if SMOKE && !isempty(SHOTS) && !shots_done[] && frames - shot_t0[] == SHOT_SETTLE
            sh = SHOTS[shot_idx[]]
            buf=Vector{UInt8}(undef,W*H*3); glReadPixels(0,0,W,H,GL_RGB,GL_UNSIGNED_BYTE,buf)
            open(joinpath(SHOTS_DIR, sh.name * ".ppm"),"w") do io; write(io,"P6\n$W $H\n255\n")
                for y in H:-1:1, x in 1:W; o=((y-1)*W+(x-1))*3; write(io,buf[o+1],buf[o+2],buf[o+3]); end; end
            println("  JM_SHOTS: dumped ", sh.name, " (", shot_idx[], "/", length(SHOTS), ")"); flush(stdout)
            isempty(PICKS) || pick_report(vp, eye, sh.name)
            if shot_idx[] < length(SHOTS)
                shot_idx[] += 1; shot_t0[] = frames + 1
                nxt = SHOTS[shot_idx[]]; CTL.view = nxt.view
                for (k, v) in nxt.env; ENV[k] = v; end
                place_at_s!(nxt.s)
            else
                shots_done[] = true
            end
        end

        frames += 1
        if STALLLOG                                   # PERF-4: name every stall (compile / GC / other)
            _now = time_ns(); _ct = UInt64(Base.cumulative_compile_time_ns()[1]); _gt = UInt64(Base.gc_time_ns())
            if STALL_PREV[1] > 0
                _wall = (_now - STALL_PREV[1]) / 1e6
                FRAME_FPS[] = FRAME_FPS[] == 0.0 ? 1000 / _wall : FRAME_FPS[] + (1000 / _wall - FRAME_FPS[]) * 0.1
                if _wall > STALL_MS && win_shown[]
                    _cm = (_ct - STALL_PREV[2]) / 1e6; _gm = (_gt - STALL_PREV[3]) / 1e6
                    STALL_N[] += 1; STALL_COMP_MS[] += _cm
                    println("  [stall] frame ", frames, " t=", round(cs.t, digits = 2), "s  ", round(_wall, digits = 1),
                            " ms (compile ", round(_cm, digits = 1), ", gc ", round(_gm, digits = 1), ")  gear ", cs.gear,
                            " thr ", round(inp.throttle, digits = 2), " clu ", round(inp.clutch, digits = 2),
                            " brk ", round(inp.brake, digits = 2), " v ", round(cs.v, digits = 1)); flush(stdout)
                end
            end
            STALL_PREV[1] = _now; STALL_PREV[2] = _ct; STALL_PREV[3] = _gt
        end
        if !win_shown[] && frames >= show_after
            println("  window revealed after ", frames, " hidden warm-up frames (", round(Int, 1000*(time() - show_t0)), " ms)"); flush(stdout)
            Base.invokelatest(perf4_reveal_marker)   # PERF-4: a marker line in --trace-compile output (warm_statements)
            reveal!()
        end
        # PERF-1 diag: JM_ALLOCSITES=1 samples allocations over frames 300..600 and prints the top sites.
        if ALLOCSITES
            if frames == 300
                @eval Main using Profile; Base.invokelatest(() -> (Profile.Allocs.clear(); Profile.Allocs.start(sample_rate = 0.02)))
            elseif frames == 600
                Base.invokelatest() do
                    Profile.Allocs.stop(); r = Profile.Allocs.fetch()
                    cnt = Dict{String,Tuple{Int,Int}}()
                    for a in r.allocs
                        site = "?"
                        for fr in a.stacktrace
                            f = string(fr.file)
                            (occursin("drive_native_mtk", f) || occursin("render.jl", f) || occursin("ai.jl", f) || occursin("drive_rt", f)) || continue
                            site = string(basename(f), ":", fr.line, " ", fr.func); break
                        end
                        c = get(cnt, site, (0, 0)); cnt[site] = (c[1] + 1, c[2] + a.size)
                    end
                    println("  [allocsites] top sites (sampled 2%, frames 300-600):")
                    for (k, v) in sort(collect(cnt), by = x -> -x[2][2])[1:min(end, 25)]
                        println("     ", lpad(round(Int, v[2]/0.02/300/1024), 6), " KB/frame  ", lpad(v[1], 6), " samples  ", k)
                    end
                    flush(stdout)
                end
            end
        end
        # SPA-FPS-1 S6: smoothed frame time for the adaptive mirror decision above. An EMA rather
        # than the instantaneous dt so one slow frame (a texture upload, a GC pause) cannot flip the
        # mirror off and on, which would itself look like strobing.
        let _nowt = time()
            if MIRROR_T0[] > 0
                dtf = _nowt - MIRROR_T0[]
                MIRROR_EMA[] = MIRROR_EMA[] == 0.0 ? dtf : (0.9 * MIRROR_EMA[] + 0.1 * dtf)
            end
            MIRROR_T0[] = _nowt
        end
        # S6b: report in BOTH arms. The first version gated this on MIRROR_ADAPT, so the control arm
        # (JM_MIRROR_ADAPT=0) printed nothing and there was no frame time to compare against -- an
        # instrument that cannot speak in the arm it is being compared to. Gate on FPSDIAG alone.
        if FPSDIAG > 0 && frames % FPSDIAG == 0
            println("  [mirror] adapt=", MIRROR_ADAPT ? 1 : 0,
                    "  frame EMA ", round(MIRROR_EMA[]*1000, digits=1), " ms   marks ", MIRROR_RESUME_MS, "/", MIRROR_ADAPT_MS, " ms   -> every ",
                    (MIRROR_ADAPT && MIRROR_STARVED[] ? MIRROR_ADAPT_N : MIRROR_EVERY),
                    " frame(s);  mirror renders skipped ", MIRROR_SKIPPED[]); flush(stdout)
        end
        if now - titleT > 0.25 && REPLAY
            carname = rep_focus[] == 0 ? (isempty(repd.names) ? "Player" : repd.names[1]) :
                      (rep_focus[] < length(repd.names) ? repd.names[rep_focus[]+1] : "AI $(rep_focus[])")
            GLFW.SetWindowTitle(win, "▶ REPLAY — $(uppercasefirst(TRACKSEL)) — 📷 $(REPLAY_CAM_LABEL[rep_cam[]]) — 🏎 $carname [$(rep_focus[]+1)/$(repd.ncar)]" *
                "  —  $(round(rep_rt[],digits=1))/$(round(rep_dur,digits=1))s  $(rep_play[] ? "▶" : "⏸")×$(rep_speed[])   ·  V angle · C car · SPACE play · ←/→ seek · ↑/↓ speed")
            titleT = now
        elseif now - titleT > 0.25
            # STANDINGS-1 S3 (2026-09-16): CAPTURE THE LIVE READOUT. S2 measured the arithmetic the
            # position indicator interpolates but said plainly that the indicator itself "was not
            # captured", because it lives in the GLFW window title and a headless run does not
            # record it. Scraping it from outside does not work either: this desktop is WAYLAND and
            # `xdotool search --name "Julia Racer"` finds nothing (only XWayland/GNOME windows
            # enumerate), which is the same wall [[no-synthetic-keys-under-wayland]] recorded from
            # the other direction. So the program prints it, which is what that note actually
            # prescribes -- an env hook, with the title as the trace.
            #
            # Sampled HERE, at the title site, deliberately: this branch is rate-limited to 0.25 s,
            # so what is printed is what a player can actually SEE, quantised exactly as the title
            # is. A per-frame sample would measure the expression rather than the readout.
            # JM_TRACE_POS=1.
            if TRACE_POS && IS_RACE && race_go[] && !isempty(AICARS)
                _p = findfirst(e -> e[1] == 0, standings())
                if _p !== nothing && _p != POS_LAST[]
                    println("  [pos] t=", round(cs.t, digits=2), "s  lap=", cs.laps + 1,
                            "  title shows P", _p, "/", length(AICARS) + 1,
                            POS_LAST[] < 0 ? "   (first sample)" : "   (was P$(POS_LAST[]))")
                    flush(stdout)
                    POS_LAST[] = _p
                end
            end
            GLFW.SetWindowTitle(win, "Julia Racer — $(uppercasefirst(TRACKSEL)) — $(round(Int,cs.v*3.6)) km/h — gear $(cs.gear == 0 ? "N" : string(cs.gear)) ($(CTL.auto ? "AUTO" : "MANUAL")) — $(round(Int,cs.rpm)) rpm" *
                (phase[] == :qual ? "  ⏱ QUALIFYING — drive a lap, then press ENTER to start the race" :
                 (!race_go[]) ? ((START_ARM && !cd_armed[] && COUNTDOWN > 0) ?
                                 "  🏁 PRESS ANY KEY TO START COUNTDOWN" :
                                 cd_left[] > 0 ? "  🏁 $(ceil(Int, cd_left[]))..." :
                                 "  🏁 GET READY — floor the throttle to start (the field launches with you)") :
                 IS_RACE ? (race_done ? "  ✦ FINISHED P$(player_finpos[])/$(length(AICARS)+1) — best $(fmt_lap(best_lap)) (started P$(player_grid[]))" :
                            "  — lap $(min(cs.laps+1,RACE_LAPS))/$RACE_LAPS" *
                            (isempty(AICARS) ? "" : "  Pos P$(findfirst(e->e[1]==0, standings()))/$(length(AICARS)+1)")) :
                           "  [$(uppercasefirst(MODE))]") *
                (FUEL_ON ? "  — fuel $(round(Int,fuel[]))L ($(round(burn_lap>0 ? fuel[]/burn_lap : 0,digits=1)) laps)" : "") *
                (cs.ontrack ? "" : "  [OFF TRACK]"))
            titleT = now
        end
    end
    telem !== nothing && close(telem)
    if ibt_samples !== nothing && !isempty(ibt_samples)
        try
            tmpl = ibt_open(IBTTMPL)
            ts = Dates.format(Dates.now(), "yyyy-mm-dd HH-MM-SS")
            odir = get(ENV, "JM_IBT_DIR", joinpath(dirname(dirname(@__DIR__)), "data", "juliaracer"))
            mkpath(odir)
            out = joinpath(odir, "lotus49_$(IBTNAME) $(ts).ibt")   # iRacing filename convention
            write_ibt(out, tmpl, ibt_samples)
            println("  wrote iRacing telemetry: ", out, "  (", length(ibt_samples), " ticks, ", filesize(out)÷1024, " KB)")
        catch e
            println("  .ibt export failed: ", e)
        end
    end
    if AI_OFFROAD_DIAG && AI_OFF[2] > 0
        println("  [ai offroad] ", AI_OFF[1], " of ", AI_OFF[2], " AI car-frames had the car centre off the drawn road (",
                round(100*AI_OFF[1]/AI_OFF[2], digits = 2), " %); worst 100 m bins (s: frames): ",
                join(["$(100k)-$(100k+100): $(v)" for (k, v) in sort(collect(AI_OFFBIN), by = x -> -x[2])[1:min(end, 8)]], ", "))
    end
    if DRIVECHECK
        d = DC[]
        println("\n  ══ DRIVEABILITY (", TRACKSEL, ") — autodrive reached s=", round(d.maxs, digits=1), " m ══")
        println("    max height above ground : ", round(d.airmax, digits=2), " m at s=", round(d.air_s, digits=1),
                "   (", d.air_bad, " frames over ", DC_AIR_MAX, " m)")
        println("    max upward velocity     : ", round(d.vzmax, digits=2), " m/s at s=", round(d.vz_s, digits=1),
                "   (", d.vz_bad, " frames over ", DC_VZ_MAX, " m/s)")
        println("    longest slow spell      : ", round(d.stuckmax, digits=1), " s at s=", round(d.stuck_s, digits=1),
                "   (stuck threshold ", DC_STUCK_S, " s under ", DC_STUCK_V, " m/s)")
        # OFFROAD-1: report the frames the height test could not see, and say so plainly. A verdict
        # that stayed silent about them is how "both tracks are survivable" was believed.
        println("    lowest groundz seen     : ", round(d.ghmin, digits=2),
                d.ghmin > -900 ? "   (the -999 off-HAT sentinel NEVER reached the physics)" : "   (sentinel seen)")
        println("    frames OFF the mesh     : ", d.off_bad,
                d.off_bad == 0 ? "   (the car never left the ground mesh)" :
                string("   highest y=", round(d.off_y, digits=2), " m at s=", round(d.off_s, digits=1),
                       "  — height there is measured against a STALE held reference, not real ground"))
        if !isempty(d.offevents)
            println("    off-mesh sites (s, y, km/h):")
            for (es, ey, ekmh) in d.offevents
                println("      s=", round(es, digits=1), "  y=", round(ey, digits=2), " m  ",
                        round(ekmh, digits=1), " km/h")
            end
        end
        if !isempty(d.events)
            println("    launch SITES (each distinct excursion above ", DC_AIR_MAX, " m; height = that excursion's PEAK):")
            for (es, eair, ekmh, ex, ez) in d.events
                println("      s=", lpad(round(es, digits=1), 9), " m   air ", lpad(round(eair, digits=2), 6),
                        " m   at ", lpad(round(ekmh, digits=0), 4), " km/h   world (",
                        round(ex, digits=1), ", ", round(ez, digits=1), ")")
            end
        end
        bad = (d.airmax > DC_AIR_MAX) + (d.vzmax > DC_VZ_MAX) + (d.stuckmax > DC_STUCK_S)
        println(bad == 0 ? "    VERDICT: CLEAN — no levitation, no bounce, never stuck" :
                           "    VERDICT: $(bad) FAILURE MODE(S) SEEN — see the lines above")
        flush(stdout)
    end
    if replay_buf !== nothing && !isempty(replay_buf)   # E18: save the all-car replay alongside the .ibt (REPLAY-2: + .jrt)
        write_replay(replay_out, replay_buf, tele_buf, REPLAY_NCAR, replay_names, CLINE; final = true)
    end
    ffb !== nothing && FFB.close_ffb(ffb)
    EngineAudio.stop!(ENG)
    GLFW.Terminate()
    GPLW_PHYS && GPLW_T[][2] > 0 && println("  GPLWALL-1 cost: ", round(1e6*GPLW_T[][1]/GPLW_T[][2], digits = 1),
                                            " us/frame over ", GPLW_T[][2], " frames (walls + drawn obstacles, contact + clamp)")
    println("bye"); flush(stdout); flush(stderr)
    # HARD exit: skip Julia's atexit handlers.  PortAudio registers one that calls Pa_Terminate, which
    # SEGFAULTS in the ALSA/PipeWire stream teardown ("free(): corrupted unsorted chunks") on this box —
    # a noisy crash AFTER the race is already fully written (telemetry/replay/result all flushed above).
    # _exit terminates the process cleanly at the OS level, so the post-race exit is no longer a crash.
    ccall(:_exit, Cvoid, (Cint,), 0)
end
main()
